import { createHash } from 'node:crypto'
import { lstat, readFile, realpath } from 'node:fs/promises'
import { resolve, sep } from 'node:path'
import { safeRepoPath } from './contracts.mjs'

const boundaries = new WeakSet()

// The root is chosen by a trusted caller. Every component is checked before the file is read.
export function createArtifactReader(root) {
  if (typeof root !== 'string' || !root) throw new TypeError('Artifact root required')
  const base = resolve(root)
  const within = (path) =>
    process.platform === 'win32'
      ? path.toLowerCase().startsWith(`${base}${sep}`.toLowerCase())
      : path.startsWith(`${base}${sep}`)
  return Object.freeze({
    async read(path) {
      if (!safeRepoPath(path)) throw new Error('UNSAFE_ARTIFACT: unsafe relative path')
      let cursor = base
      for (const part of path.split('/')) {
        cursor = resolve(cursor, part)
        if (!within(cursor)) throw new Error('UNSAFE_ARTIFACT: outside root')
        const stat = await lstat(cursor)
        if (stat.isSymbolicLink()) throw new Error('UNSAFE_ARTIFACT: symlink')
      }
      const canonical = await realpath(cursor)
      if (!within(canonical)) throw new Error('UNSAFE_ARTIFACT: realpath escape')
      const bytes = await readFile(cursor)
      return Object.freeze({
        path,
        bytes,
        sha256: createHash('sha256').update(bytes).digest('hex'),
      })
    },
  })
}

// Only a trusted integration supplies verify: it must inspect actual raw artifacts, hashes,
// complete execution, independent receipt, scope and bindings. No JSON field is an authority.
export function createEvidenceBoundary({ verify } = {}) {
  if (typeof verify !== 'function') throw new TypeError('Trusted evidence verifier required')
  const boundary = Object.freeze({ verify: (kind, ref, expected) => verify(kind, ref, expected) })
  boundaries.add(boundary)
  return boundary
}

export const isEvidenceBoundary = (x) => boundaries.has(x)

export async function verifyArtifactHash(reader, descriptor) {
  if (
    typeof reader?.read !== 'function' ||
    !safeRepoPath(descriptor?.path) ||
    !/^[a-f0-9]{64}$/.test(descriptor?.sha256 ?? '')
  )
    return false
  try {
    return (await reader.read(descriptor.path)).sha256 === descriptor.sha256
  } catch {
    return false
  }
}

export async function verifyGate(boundary, kind, ref, expected) {
  if (
    !isEvidenceBoundary(boundary) ||
    !ref ||
    typeof ref !== 'object' ||
    Array.isArray(ref) ||
    ref.kind !== kind ||
    ref.status !== 'PASS' ||
    ref.complete !== true ||
    ref.scope !== 'full' ||
    !safeRepoPath(ref.artifact?.path) ||
    !/^[a-f0-9]{64}$/.test(ref.artifact?.sha256 ?? '') ||
    !ref.bindings ||
    typeof ref.bindings !== 'object' ||
    Object.entries(expected).some(([k, v]) => ref.bindings[k] !== v)
  )
    return false
  try {
    return (await boundary.verify(kind, ref, expected)) === true
  } catch {
    return false
  }
}
#!/usr/bin/env node
import { readFile } from 'node:fs/promises'
import { isAbsolute } from 'node:path'
import { checkDirection, createDirection, planDirection } from './bootstrap.mjs'
import { refreshStatus } from './status.mjs'
import { createArtifactReader } from './evidence.mjs'
import { createHash } from 'node:crypto'
import { spawnSync } from 'node:child_process'
import { relative } from 'node:path'

const blocked = (code, detail) => ({ ok: false, status: 'BLOCKED', code, detail })
const [command, path, ...extra] = process.argv.slice(2)
let result
if (!['plan', 'create', 'check', 'status'].includes(command)) {
  result = {
    ok: false,
    status: 'NOT_IMPLEMENTED',
    code: 'COMMAND_NOT_IMPLEMENTED',
    detail: 'Supported: plan, create, check, status. Other workflow commands require later tasks.',
  }
} else if (
  !path ||
  (command === 'status'
    ? extra.length > 1 || (extra.length === 1 && extra[0] !== '--write')
    : extra.length) ||
  !isAbsolute(path)
) {
  result = blocked('ARGUMENTS', 'One absolute JSON request or manifest path required')
} else {
  try {
    if (command === 'check') result = await checkDirection(path)
    else if (command === 'status') {
      const checked = await checkDirection(path)
      if (!checked.ok) result = checked
      else {
        const bytes = await readFile(path)
        const manifest = JSON.parse(bytes)
        const root = manifest.owner.worktree
        const tracked = spawnSync(
          'git',
          [
            '-c',
            'core.autocrlf=false',
            '-c',
            'core.longpaths=true',
            'ls-files',
            '--error-unmatch',
            '--',
            relative(root, path),
          ],
          { cwd: root, encoding: 'utf8' },
        )
        if (tracked.status !== 0) throw new Error('MANIFEST_NOT_TRACKED')
        const reader = createArtifactReader(root)
        const change =
          manifest.stages.find((s) => s.phase !== 'CLOSED')?.change ?? manifest.stages.at(-1).change
        let tasksText = '',
          trace
        const sourceIssues = []
        try {
          tasksText = (await reader.read(`openspec/changes/${change}/tasks.md`)).bytes.toString(
            'utf8',
          )
        } catch {
          sourceIssues.push({
            code: 'TASK_SOURCE_UNAVAILABLE',
            path: `openspec/changes/${change}/tasks.md`,
          })
        }
        try {
          trace = JSON.parse(
            (await reader.read(`openspec/changes/${change}/traceability.json`)).bytes,
          )
        } catch {
          sourceIssues.push({
            code: 'TRACE_SOURCE_UNAVAILABLE',
            path: `openspec/changes/${change}/traceability.json`,
          })
        }
        const snapshot = {
          sourceSha256: createHash('sha256').update(bytes).digest('hex'),
          configSha256: manifest.policy.sha256,
        }
        result = await refreshStatus({
          manifest,
          ownerRoot: root,
          tasksText,
          trace,
          sourceIssues,
          snapshot,
          updatedAt: new Date().toISOString(),
          write: extra[0] === '--write',
        })
      }
    } else {
      const request = JSON.parse(await readFile(path, 'utf8'))
      result = command === 'plan' ? await planDirection(request) : await createDirection(request)
    }
  } catch (error) {
    result = blocked('INPUT', error.message)
  }
}
process.stdout.write(`${JSON.stringify(result)}\n`)
process.exitCode = result.ok ? 0 : 2

import { createHash } from 'node:crypto'
